//! Attention plan 01a199e1b177752e84dad5dc990e6a15, step 1: record the actor at the
//! authenticated boundary. A user-role timeline message is not proof that a person sent it.

use serde_json::Value;

use super::model::Command;
use crate::authz::Caller;
use crate::hub::Hub;

/// What a command a person sends an agent is as their use of it (step 1): every one they send counts, by every path.
/// Requests generated by a viewer (snapshots, completion, inventory, a skill's text, the skills read again) and kiln's
/// own words to an agent aren't deliberate uses. Every command is named, so a new one is decided here, not missed.
pub fn command_kind(command: &Command) -> Option<&'static str> {
    match command {
        Command::StateRead { .. } => None,
        Command::AtState { command, .. } => command_kind(command),
        Command::Admit { .. } | Command::MailAck { .. } | Command::MailPeers { .. } | Command::MailHandoff { .. } => None,
        Command::Send { .. } | Command::SkillRun { .. } => Some("message"),
        Command::Approve { .. } | Command::Resume => Some("answer"),
        Command::Interrupt | Command::ForceStop | Command::Restart | Command::StopTask { .. } | Command::StopTasks
        | Command::SetMode { .. } | Command::SetModel { .. } | Command::SetEffort { .. } | Command::SetSpeed { .. }
        | Command::Control { .. } | Command::MoveTo { .. } | Command::QueueEdit { .. } | Command::QueueRemove { .. }
        | Command::QueueMove { .. } | Command::QueueSendNow { .. } | Command::QueueSteer { .. }
        | Command::Pause { .. } | Command::Perms { .. } | Command::Branch { .. } | Command::PauseAt { .. }
        | Command::MaxSubagents { .. } | Command::MoveOnLimit { .. } | Command::AutoResume { .. }
        | Command::McpEnable { .. } | Command::McpReconnect { .. } | Command::McpAuth { .. } | Command::McpAdd { .. }
        | Command::McpRemove { .. } | Command::RemoveTask { .. } | Command::OwnEdits { .. } => Some("command"),
        // Reads and refreshes.
        Command::Snapshot | Command::McpRefresh | Command::Suggest { .. } | Command::SkillView { .. } | Command::SkillsReload => None,
        // kiln's own: a move's progress, a hand-over's word, another session's usage limit.
        Command::Moving { .. } | Command::HandedOver { .. } | Command::LimitHold { .. } => None,
    }
}

pub async fn record(hub: &Hub, caller: &Caller, agent: &str, kind: &str, key: &str, at: i64) {
    if let Err(error) = super::attention::record_person(hub, caller, agent, kind, key, at).await {
        tracing::warn!(%agent, %error, "an accepted person's action could not be recorded for Mission Control");
    }
}

/// A transport retry has the same key, so it can't teach the model a second use.
pub struct Prepared {
    pub kind: &'static str,
    pub key: String,
    /// Captured before dispatch so work caused by the action cannot predict that action.
    pub at: i64,
    pub response: Option<super::attention::HumanResponse>,
}

pub fn prepare(hub:&Hub,agent:&str,command: &Command, transport_key: Option<&str>) -> Option<Prepared> {
    let at=crate::util::now_ms();
    prepare_from_info(command,transport_key,at,hub.harness.info(agent).as_ref())
}

#[cfg(test)]
pub fn prepare_at(command: &Command, transport_key: Option<&str>, at: i64) -> Option<Prepared> {
    prepare_from_info(command,transport_key,at,None)
}

pub fn prepare_from_info(command:&Command,transport_key:Option<&str>,at:i64,info:Option<&super::session::Info>)->Option<Prepared>{
    let kind = command_kind(command)?;
    let message = super::registry::message_id(command);
    let approval = match command { Command::Approve { id, .. } => Some(super::attention::approval_key(id,info.and_then(|i|i.approvals.iter().filter(|a|&a.id==id).max_by_key(|a|a.at)).map(|a|a.at).filter(|at|*at>0))), _ => None };
    let known_approval=info.is_some_and(|i|matches!(command,Command::Approve{id,..} if i.approvals.iter().any(|a|&a.id==id && a.at>0)));
    let key = message.as_deref().or(if known_approval{approval.as_deref()}else{transport_key.or(approval.as_deref())}).map(str::to_owned).unwrap_or_else(crate::util::new_id);
    let response=match command { Command::Approve{id,..}=>Some(super::attention::HumanResponse::Approval(id.clone())),Command::Resume=>Some(super::attention::HumanResponse::Goals),Command::Restart=>Some(super::attention::HumanResponse::Restart),_=>None };
    let response=response.and_then(|selector|info.and_then(|i|super::attention::bind_response(i,&selector)));
    Some(Prepared { kind, key, at, response })
}

pub async fn command(hub: &Hub, caller: &Caller, agent: &str, command: &Command, transport_key: Option<&str>, at: i64, source:Option<&super::session::Info>) {
    if let Some(prepared) = prepare_from_info(command, transport_key, at,source) {
        record_prepared(hub, caller, agent, prepared).await;
    }
}

pub async fn record_prepared(hub: &Hub, caller: &Caller, agent: &str, prepared: Prepared) {
    record(hub,caller,agent,prepared.kind,&prepared.key,prepared.at).await;
    if let Some(response)=prepared.response { response_to(hub,caller,agent,&prepared.key,response,prepared.at).await; }
}

pub async fn response_to(hub: &Hub, caller: &Caller, agent: &str, key: &str, response: super::attention::HumanResponse, at: i64) {
    if let Err(error)=super::attention::record_response(hub,caller,agent,key,response,at).await {
        tracing::warn!(%agent,%error,"an accepted human response could not be recorded for Mission Control");
    }
}

/// The operations that are a person's command to an agent (step 1): sending, starting, interrupting and ending it, its
/// goals, asking about its conversation, a change request from its work, and landing its workspace. Reads, waits and an
/// agent's own git credential aren't.
pub fn tracks_operation(name: &str) -> bool {
    matches!(name, "agents.send" | "agents.start" | "agents.interrupt" | "agents.stop" | "agents.about" | "agents.change" | "agents.land") || name.starts_with("goals.") && !matches!(name, "goals.get")
}

pub fn prepare_operation(hub:&Hub,name:&str,input:&Value)->Option<super::attention::HumanResponse>{
    if name!="goals.control" || !matches!(input.get("action").and_then(Value::as_str),Some("resume"|"start")){return None;}
    let info=hub.harness.info(input.get("agent")?.as_str()?)?;
    super::attention::bind_response(&info,&super::attention::HumanResponse::Goals)
}

/// MCP, CLI, and HTTP operation routes all meet here, after authorization and a successful action.
pub async fn operation(hub: &Hub, caller: &Caller, name: &str, input: &Value, output: &Value, at: i64, response:Option<super::attention::HumanResponse>) {
    if !tracks_operation(name) || output.get("sent").and_then(Value::as_bool) == Some(false) {
        return;
    }
    let kind = match name {
        "agents.send" => "message",
        "goals.control" | "goals.done" => "answer",
        _ => "command",
    };
    let key = output.get("message").and_then(Value::as_str).or_else(|| input.get("key").and_then(Value::as_str)).map(str::to_owned).unwrap_or_else(crate::util::new_id);
    if name == "agents.start" {
        if let Some(agents) = output.get("agents").and_then(Value::as_array) {
            for id in agents.iter().filter_map(|a| a.get("id").and_then(Value::as_str)) {
                record(hub, caller, id, if input.get("prompt").and_then(Value::as_str).is_some() { "message" } else { "command" }, id, at).await;
            }
        }
    } else if let Some(id) = input.get("agent").and_then(Value::as_str) {
        let key=format!("{name}:{key}");
        record(hub, caller, id, kind, &key, at).await;
        if let Some(response)=response { response_to(hub,caller,id,&key,response,at).await; }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn mc_attention_approval_interest_is_per_occurrence_not_reused_provider_id()->anyhow::Result<()>{
        use super::super::{session::{Info,ApprovalBrief},model::{ToolKind,Decision}};
        let info=|at|Info{approvals:vec![ApprovalBrief{id:"rpc:1".into(),tool:ToolKind::Question,tool_name:"ask".into(),title:"Choose".into(),at,agent:None}],..Info::default()};
        let command=Command::Approve{id:"rpc:1".into(),decision:Decision::Allow,message:None,always:None,answers:None,choices:None};
        let a=prepare_from_info(&command,Some("first-frame"),200,Some(&info(100))).ok_or_else(||anyhow::anyhow!("missing first answer"))?;
        let retry=prepare_from_info(&command,Some("retry-frame"),205,Some(&info(100))).ok_or_else(||anyhow::anyhow!("missing retry"))?;
        let b=prepare_from_info(&command,Some("later-frame"),1100,Some(&info(1000))).ok_or_else(||anyhow::anyhow!("missing later answer"))?;
        assert_eq!(a.key,retry.key);assert_ne!(a.key,b.key);Ok(())
    }
    #[test]
    fn mc_attention_response_bindings_require_a_known_predispatch_request(){
        use super::super::{session::{Info,Held},model::{ExitInfo,Status}};
        let held=Info{held:Some(Held{why:"Review".into(),plan:None,since:100}),..Info::default()};
        let response=prepare_from_info(&Command::Resume,None,200,Some(&held)).and_then(|p|p.response);
        assert!(matches!(response,Some(super::super::attention::HumanResponse::Bound(_))));
        assert!(prepare_at(&Command::Resume,None,200).and_then(|p|p.response).is_none());
        let stopped=Info{status:Status::Exited,exit:Some(ExitInfo{code:None,error:Some("Stopped".into()),at:100,again_at:None}),..Info::default()};
        assert!(matches!(prepare_from_info(&Command::Restart,None,200,Some(&stopped)).and_then(|p|p.response),Some(super::super::attention::HumanResponse::Bound(_))));
    }
    #[test]
    fn mc_attention_choice_time_excludes_the_turn_caused_by_that_choice()->anyhow::Result<()>{
        use kiln_ci::attention::{Model,Use,UseKind,rank};
        let prepared=prepare_at(&Command::Interrupt,Some("request"),100).ok_or_else(||anyhow::anyhow!("missing deliberate command"))?;
        // The command was received at 100; its caused turn began at 150 and completed
        // dispatch at 200. Recording after dispatch must still use receipt time.
        let model=Model{decay:0.5,weights:[(UseKind::Message,1.0),(UseKind::Turn,1.0)].into_iter().collect(),range_weight:None,scales:Default::default(),family:Default::default()};
        let before=vec![Use{agent:"a".into(),kind:UseKind::Message,at:1},Use{agent:"b".into(),kind:UseKind::Message,at:1}];
        let mut after=before.clone();after.push(Use{agent:"b".into(),kind:UseKind::Turn,at:150});
        let ids=vec!["a".into(),"b".into()];
        assert_eq!(rank(Some(&model),&before,&ids,prepared.at),rank(Some(&model),&after,&ids,prepared.at));
        assert_eq!(rank(Some(&model),&after,&ids,200).first().map(|r|r.agent.as_str()),Some("b"),"using completion time would leak caused work into the choice");
        Ok(())
    }

    #[test]
    fn mc_attention_broadcast_records_each_target_once_at_receipt_time()->anyhow::Result<()>{
        crate::rt::block_on(async{
            let hub=crate::hub::tests::scratch_hub().await?;
            for id in ["a","b"]{
                let info=super::super::session::Info{id:id.into(),status:super::super::model::Status::Idle,..Default::default()};
                hub.harness.ingest(&super::super::registry::Location::Local,id,super::super::core::Update::Open{info:Box::new(info),since:None}).await;
            }
            let prepared=prepare_at(&Command::Interrupt,Some("broadcast"),100).ok_or_else(||anyhow::anyhow!("missing command"))?;
            for id in ["a","b","a"]{record(&hub,&Caller::owner(),id,prepared.kind,&prepared.key,prepared.at).await;}
            let rows:Vec<(String,i64)>=hub.store.call(|c|{let mut q=c.prepare("SELECT chosen,at FROM attention_choices WHERE principal='owner' ORDER BY chosen")?;Ok(q.query_map([],|r|Ok((r.get(0)?,r.get(1)?)))?.collect::<Result<_,_>>()?)}).await?;
            assert_eq!(rows,vec![("a".into(),100),("b".into(),100)]);
            Ok(())
        })
    }

    #[test]
    fn mc_attention_refreshes_never_count_as_person_interaction() -> anyhow::Result<()> {
        for read in [json!({"type":"snapshot"}), json!({"type":"mcp_refresh"}), json!({"type":"suggest","client":"c","query":"a"}), json!({"type":"skill_view","name":"review","client":"c"}), json!({"type":"skills_reload"})] {
            assert_eq!(command_kind(&serde_json::from_value(read.clone())?), None, "{read}");
        }
        assert_eq!(command_kind(&Command::Interrupt), Some("command"));
        assert_eq!(command_kind(&Command::Resume), Some("answer"));
        Ok(())
    }

    /// Step 1: every command a person sends an agent is their use of it, those it once missed included.
    #[test]
    fn mc_attention_every_command_a_person_sends_is_their_use() -> anyhow::Result<()> {
        for sent in [
            json!({"type":"branch","words":"try it the other way"}),
            json!({"type":"pause_at","percent":80}),
            json!({"type":"max_subagents","count":2}),
            json!({"type":"move_on_limit","on":true}),
            json!({"type":"auto_resume","on":false}),
            json!({"type":"mcp_enable","name":"docs","enabled":false}),
            json!({"type":"mcp_reconnect","name":"docs"}),
            json!({"type":"mcp_auth","name":"docs"}),
            json!({"type":"mcp_add","name":"docs"}),
            json!({"type":"mcp_remove","name":"docs"}),
            json!({"type":"remove_task","task":"t1"}),
            json!({"type":"own_edits","client":"c","by":"main"}),
        ] {
            let command: Command = serde_json::from_value(sent.clone())?;
            assert_eq!(command_kind(&command), Some("command"), "{sent}");
            assert!(prepare_at(&command, Some("frame"), 100).is_some(), "{sent} is recorded at the authenticated boundary");
        }
        Ok(())
    }

    #[test]
    fn mc_attention_read_only_tools_never_count_as_choices() {
        assert!(!tracks_operation("agents.list"));
        assert!(!tracks_operation("agents.get"));
        assert!(!tracks_operation("goals.get"));
        assert!(!tracks_operation("agents.wait"), "a wait takes the waiter's own messages; it commands no agent");
        assert!(!tracks_operation("agents.credential"), "only the agent itself is given one");
        for op in ["agents.send", "goals.control", "agents.about", "agents.change", "agents.land"] {
            assert!(tracks_operation(op), "{op}");
        }
    }
}
